from collections import deque

def is_bipartite(edges, n):
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)
    color = [-1] * n
    for start in range(n):
        if color[start] == -1:
            queue = deque([start])
            color[start] = 0
            while queue:
                node = queue.popleft()
                for nb in adj[node]:
                    if color[nb] == -1:
                        color[nb] = 1 - color[node]
                        queue.append(nb)
                    elif color[nb] == color[node]:
                        return False, None
    return True, color

def girth(edges, n):
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)
    min_cycle = float('inf')
    for start in range(n):
        dist = [-1] * n
        dist[start] = 0
        queue = deque([(start, -1)])
        while queue:
            node, parent = queue.popleft()
            for nb in adj[node]:
                if nb == parent:
                    continue
                if dist[nb] == -1:
                    dist[nb] = dist[node] + 1
                    queue.append((nb, node))
                else:
                    cycle_len = dist[node] + dist[nb] + 1
                    min_cycle = min(min_cycle, cycle_len)
    return min_cycle

